import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Hypothesis-Testing.md","filePath":"manual-zh/Hypothesis-Testing.md","lastUpdated":1785684581000}'),s={name:"manual-zh/Hypothesis-Testing.md"};function d(n,t,h,i,l,p){return e(),r("div",null,[...t[0]||(t[0]=[o('<h3 id="_5-3-假设检验" tabindex="-1">5.3 假设检验 <a class="header-anchor" href="#_5-3-假设检验" aria-label="Permalink to &quot;5.3 假设检验&quot;">​</a></h3><p>统计分析最基本的目的之一是假设检验。研究人员通常需要对一组数据的假设进行检验。例如，她可能想检验一组数据是否与另一组来自同一分布，或者数据集的均值是否与某个特定值显著不同。本节仅介绍 PSPP 提供的一些可能检验。</p><p>研究人员首先提出一个 <em>原假设</em>。通常这是一个他怀疑为假的假设。例如，如果他怀疑 A 大于 B，他会把原假设表述为 <em>A = B</em>。2</p><p><em>p 值</em> 是假设检验中一个反复出现的概念。它是当原假设事实上为真时，能够得出暗示原假设为假的证据的最高可接受概率。注意，这不同于“犯错误的概率”，也不同于“在原假设为真时拒绝它的概率”。</p><table tabindex="0"><thead><tr><th>• 均值差异检验</th><th></th><th></th></tr></thead><tbody><tr><td>• 线性回归</td><td></td><td></td></tr></tbody></table><h4 id="脚注" tabindex="-1">脚注 <a class="header-anchor" href="#脚注" aria-label="Permalink to &quot;脚注&quot;">​</a></h4><h5 id="_2" tabindex="-1">(2) <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;(2)&quot;">​</a></h5><p>本例假设已经证明 B 不大于 A。</p>',8)])])}const c=a(s,[["render",d]]);export{m as __pageData,c as default};
